// Ported from the Node app's Sequelize model TransportAttendance (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class TransportAttendanceConfiguration : IEntityTypeConfiguration<TransportAttendance>
{
    public void Configure(EntityTypeBuilder<TransportAttendance> builder)
    {
        builder.ToTable("transport_attendance", t =>
        {
            t.HasCheckConstraint("CK_transport_attendance_trip", "[trip] IN (N'morning', N'evening')");
            t.HasCheckConstraint("CK_transport_attendance_status", "[status] IN (N'boarded', N'absent')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.Trip).HasColumnName("trip").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired();
        builder.HasIndex(e => new { e.StudentId, e.Date, e.Trip }).IsUnique().HasDatabaseName("uq_transport_att");
        builder.HasOne(e => e.Student).WithMany(p => p.TransportAttendances).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
